select throws_ok($$select public.mark_service_request_ready('a2140000-0000-4000-8000-000000000500',1,'Tentative de validation historique','catalog214-ready-invalid')$$,'55000','REQUEST_PUBLISHED_CLIENT_QUESTIONNAIRE_REQUIRED','old malformed draft cannot be promoted through direct RPC');
